import torch, b200probe, inspect
print(inspect.signature(b200probe.cuda_kernel), inspect.signature(b200probe.harness_time))
src = r'''
extern "C" __global__ void __launch_bounds__(128) rec(const float* __restrict__ x, float* __restrict__ y, int* sm, unsigned long long* ts){
  unsigned s; asm volatile("mov.u32 %0, %%smid;":"=r"(s));
  unsigned long long t; asm volatile("mov.u64 %0, %%globaltimer;":"=l"(t));
  long long row = blockIdx.y; int col = (blockIdx.x*128+threadIdx.x)*8;
  const float* g = x + row*10240 + col;
  float a[8], b[8];
  #pragma unroll
  for(int i=0;i<8;i++){a[i]=g[i]; b[i]=g[5120+i];}
  #pragma unroll
  for(int i=0;i<8;i++) y[row*5120+col+i]=a[i]*b[i];
  if(threadIdx.x==0){int bi=blockIdx.y*gridDim.x+blockIdx.x; sm[bi]=s; ts[bi]=t;}
}
'''
k = b200probe.cuda_kernel(src, "rec")
import collections
for rows in [128, 422, 512, 2048]:
    x = torch.randn(rows, 10240, device='cuda'); y = torch.empty(rows,5120,device='cuda')
    n = 5*rows
    sm = torch.full((n,), -1, dtype=torch.int32, device='cuda'); ts = torch.zeros(n, dtype=torch.int64, device='cuda')
    b200probe.flush_l2()
    k((5, rows), (128,), x, y, sm, ts); torch.cuda.synchronize()
    s = sm.cpu().numpy(); t = ts.cpu().numpy()
    import numpy as np
    cnt = np.bincount(s, minlength=148)
    order = np.argsort(t, kind='stable')
    first = s[order[:148]]
    t0 = t.min()
    print(f"rows {rows}: CTAs {n}, SMs used {int((cnt>0).sum())}, per-SM min/max {cnt.min()}/{cnt.max()}, "
          f"sm<74: {cnt[:74].sum()} sm>=74: {cnt[74:].sum()}, even: {cnt[0::2].sum()} odd: {cnt[1::2].sum()}")
    print("  first 40 SMs by start time:", list(first[:40]))
    print("  start spread ns: first148 %d, all %d" % (t[order[147]]-t0 if n>147 else -1, t.max()-t0))
    # first 148 CTAs distinct SMs?
    print("  distinct SMs among first 148 starts:", len(set(first.tolist())))

