import torch, b200probe, numpy as np
src = r'''
extern "C" __global__ void lat(const unsigned* buf, const long long* off, int n, unsigned* lat, int target, int* flag, unsigned* sink){
  __shared__ unsigned sh[2];
  unsigned s; asm volatile("mov.u32 %0, %%smid;":"=r"(s));
  if (s != (unsigned)target || threadIdx.x) return;
  if (atomicCAS(flag, 0, 1) != 0) return;
  unsigned v = 0;
  for (int i = 0; i < n; i++) {
    const unsigned* p = buf + (off[i] >> 2) + v;   // v is always 0 (buffer zero), but opaque
    unsigned long long t0, t1;
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t0) :: "memory");
    asm volatile("ld.global.cg.u32 %0, [%1];" : "=r"(v) : "l"(p) : "memory");
    asm volatile("st.volatile.shared.u32 [%0], %1;" :: "r"((unsigned)__cvta_generic_to_shared(sh)), "r"(v) : "memory");
    asm volatile("mov.u64 %0, %%clock64;" : "=l"(t1) :: "memory");
    lat[i] = (unsigned)(t1 - t0);
  }
  sink[0] = v + sh[0];
}
'''
k = b200probe.cuda_kernel(src, "lat")
sass = b200probe.sass(src)
lines = [l for l in sass.splitlines() if any(x in l for x in ("CS2R","LDG","STS","DEPBAR"))]
print("\n".join(lines[:12]))
buf = torch.zeros(64<<20 >> 2, dtype=torch.int32, device='cuda')
sink = torch.zeros(4, dtype=torch.int32, device='cuda')
N = 2048
offs = torch.tensor((np.arange(N, dtype=np.int64) * 4096) % (64<<20), device='cuda')
for sm in [0, 74]:
    flag = torch.zeros(1, dtype=torch.int32, device='cuda'); out = torch.zeros(N, dtype=torch.int32, device='cuda')
    b200probe.flush_l2()
    k((592,), (32,), buf, offs, N, out, sm, flag, sink); torch.cuda.synchronize()
    a = out.cpu().numpy(); print(sm, flag.item(), np.percentile(a,[5,50,95]))
    flag.zero_()
    k((592,), (32,), buf, offs, N, out, sm, flag, sink); torch.cuda.synchronize()
    a = out.cpu().numpy(); print(sm, "warm", np.percentile(a,[5,25,50,75,95]))

